import { create } from 'zustand'
import { ORGANIZATION_INDEX_KEY } from '@/constants'
import { createJSONStorage, persist } from 'zustand/middleware'
import AsyncStorage from '@react-native-async-storage/async-storage'

interface OrganizationStore {
	currentOrganizationIndex: number
	setCurrentOrganizationIndex: (index: number) => void
}

export const useOrganizationStore = create(
	persist<OrganizationStore>(
		(set) => ({
			currentOrganizationIndex: 0,
			setCurrentOrganizationIndex: (index: number) => {
				set({ currentOrganizationIndex: index })
			}
		}),
		{
			name: ORGANIZATION_INDEX_KEY,
			storage: createJSONStorage(() => AsyncStorage)
		}
	)
)
